import{_ as t,c as a,o as s,a3 as n}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Maintenance setup","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/setup/index.md","filePath":"master/supply-chain/maintenance/setup/index.md","lastUpdated":1792041590000}'),r={name:"master/supply-chain/maintenance/setup/index.md"};function o(i,e,l,h,p,d){return s(),a("div",null,e[0]||(e[0]=[n(`<h1 id="maintenance-setup" tabindex="-1">Maintenance setup <a class="header-anchor" href="#maintenance-setup" aria-label="Permalink to &quot;Maintenance setup&quot;">​</a></h1><p>Setup is the small amount of work you do before the first request. You define who does maintenance, how you group equipment, and which steps a job goes through. Once these records exist, adding equipment and requests takes seconds.</p><blockquote><p><strong>In simple words:</strong> Setup answers three questions: who fixes things, what kinds of equipment do we have, and what are the steps of a job.</p></blockquote><p>Open <code>Maintenance → Configurations</code>. The <strong>Configurations</strong> menu lists <strong>Stages</strong>, <strong>Teams</strong> and <strong>Categories</strong>.</p><h2 id="how-the-three-records-relate" tabindex="-1">How the three records relate <a class="header-anchor" href="#how-the-three-records-relate" aria-label="Permalink to &quot;How the three records relate&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Category  ──►  Equipment  ◄──  Team</span></span>
<span class="line"><span>(Responsible)      │          (members)</span></span>
<span class="line"><span>                   ▼</span></span>
<span class="line"><span>              Request  ──►  moves through Stages</span></span></code></pre></div><ul><li>A <strong>category</strong> groups similar equipment, such as <strong>Packaging Machines</strong>. It names a <strong>Responsible</strong> person.</li><li>A <strong>team</strong> is a group of technicians, such as <strong>Electrical Maintenance Team</strong>.</li><li><strong>Equipment</strong> points to one category and one team.</li><li>A <strong>request</strong> picks equipment, then fills the category, team and responsible person from it.</li><li><strong>Stages</strong> are the steps shown on every request.</li></ul><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./maintenance-teams.html">Maintenance teams</a></td><td>Create teams and add members</td></tr><tr><td><a href="./equipment-categories.html">Equipment categories</a></td><td>Group equipment and set the default responsible person</td></tr><tr><td><a href="./stages.html">Stages</a></td><td>The steps of a request and the Done flag</td></tr></tbody></table><h2 id="suggested-order" tabindex="-1">Suggested order <a class="header-anchor" href="#suggested-order" aria-label="Permalink to &quot;Suggested order&quot;">​</a></h2><ol><li>Check the four stages. Change them only if your team works differently.</li><li>Create a category for each kind of equipment.</li><li>Create a team for each group of technicians.</li><li>Add your equipment. See <a href="./../equipment/add-equipment.html">Add equipment</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Users must exist before you can name them as responsible persons or team members. See <a href="./../../../general-settings/users/manage-users.html">Manage users</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../get-started/first-steps.html">First steps</a></li><li><a href="./../equipment/add-equipment.html">Add equipment</a></li><li><a href="./../requests/create-request.html">Create a maintenance request</a></li></ul>`,14)]))}const m=t(r,[["render",o]]);export{c as __pageData,m as default};
